package com.supermarkettracker.infrastructure.persistence.adapter;
import com.supermarkettracker.domain.model.*; import com.supermarkettracker.domain.model.valueobject.Identificador; import com.supermarkettracker.domain.repository.EmpresaRepository; import com.supermarkettracker.infrastructure.persistence.mapper.EmpresaPersistenceMapper; import com.supermarkettracker.infrastructure.persistence.repository.EmpresaJpaRepository; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class EmpresaRepositoryJpaAdapter implements EmpresaRepository { private final EmpresaJpaRepository jpa; private final EmpresaPersistenceMapper mapper; public EmpresaRepositoryJpaAdapter(EmpresaJpaRepository jpa, EmpresaPersistenceMapper mapper){this.jpa=jpa;this.mapper=mapper;} public Empresa salvar(Empresa e){return mapper.toDomain(jpa.save(mapper.toEntity(e)));} public Optional<Empresa> buscarPorId(Identificador id){return jpa.findById(id.valor()).map(mapper::toDomain);} }
